import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.xlC3Vtar.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"SnipX","text":"极致轻量的截图工具","tagline":"体积 < 1MB，启动 < 500ms，功能强大的 Windows 截图工具","image":{"src":"/hero-image.png","alt":"SnipX"},"actions":[{"theme":"brand","text":"立即下载","link":"/download"},{"theme":"alt","text":"快速开始","link":"/guide/getting-started"},{"theme":"alt","text":"GitHub","link":"https://github.com/vogadero/SnipX"}]},"features":[{"icon":"🪶","title":"极致轻量","details":"体积 < 1MB，启动 < 500ms，内存占用 < 10MB，CPU 占用 < 1%"},{"icon":"📸","title":"强大截图","details":"支持区域、全屏、窗口、滚动截图，多显示器完美支持，智能窗口检测"},{"icon":"🎨","title":"10 种标注工具","details":"矩形、椭圆、箭头、铅笔、文字、直线、序号、高亮、马赛克、模糊"},{"icon":"🔧","title":"完整编辑","details":"选中、移动、调整大小、删除、撤销/重做，支持颜色和粗细自定义"},{"icon":"💾","title":"多格式保存","details":"支持 PNG、JPG、BMP 格式，可调质量，自动保存，时间戳命名"},{"icon":"🎯","title":"取色器","details":"RGB/HSL/HEX 颜色拾取，10x 放大镜，一键复制颜色值"},{"icon":"📌","title":"贴图功能","details":"截图贴回桌面，支持缩放、透明度调节、鼠标穿透"},{"icon":"🎬","title":"录屏功能","details":"屏幕帧序列录制，提供 GIF 导出入口"},{"icon":"⌨️","title":"快捷键支持","details":"丰富的快捷键，Alt+X 启动区域截图，Alt+F 全屏截图，Ctrl+S 保存，Ctrl+C 复制"},{"icon":"🌍","title":"多语言","details":"支持中文、英文，可扩展其他语言"},{"icon":"⚙️","title":"灵活设置","details":"启动模式、开机自启、托盘图标、默认格式、保存路径等"},{"icon":"🚀","title":"高性能","details":"纯 C++ Win32 API，无第三方依赖，性能优异"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function n(l,t,d,s,h,c){return a(),i("div",null,[...t[0]||(t[0]=[r('<h2 id="🎉-为什么选择-snipx" tabindex="-1">🎉 为什么选择 SnipX？ <a class="header-anchor" href="#🎉-为什么选择-snipx" aria-label="Permalink to &quot;🎉 为什么选择 SnipX？&quot;">​</a></h2><h3 id="极致轻量-快如闪电" tabindex="-1">极致轻量，快如闪电 <a class="header-anchor" href="#极致轻量-快如闪电" aria-label="Permalink to &quot;极致轻量，快如闪电&quot;">​</a></h3><p>SnipX 采用纯 C++ Win32 API 开发，没有任何第三方依赖，体积小于 1MB，启动速度小于 500ms。相比其他截图工具动辄几十 MB 的体积，SnipX 让你的系统更加轻盈。</p><h3 id="功能强大-应有尽有" tabindex="-1">功能强大，应有尽有 <a class="header-anchor" href="#功能强大-应有尽有" aria-label="Permalink to &quot;功能强大，应有尽有&quot;">​</a></h3><p>虽然体积小，但功能一点也不少。10 种标注工具、取色器、贴图、录屏、多格式保存、快捷键支持等功能应有尽有，满足你的所有截图需求。</p><h3 id="简单易用-开箱即用" tabindex="-1">简单易用，开箱即用 <a class="header-anchor" href="#简单易用-开箱即用" aria-label="Permalink to &quot;简单易用，开箱即用&quot;">​</a></h3><p>无需安装，下载即用。简洁的界面设计，直观的操作方式，让你快速上手。丰富的快捷键支持，让截图更加高效。</p><h3 id="开源免费-持续更新" tabindex="-1">开源免费，持续更新 <a class="header-anchor" href="#开源免费-持续更新" aria-label="Permalink to &quot;开源免费，持续更新&quot;">​</a></h3><p>SnipX 采用 MIT 许可证开源，完全免费使用。我们会持续更新和改进，欢迎提出建议和反馈。</p><hr><h2 id="📸-功能展示" tabindex="-1">📸 功能展示 <a class="header-anchor" href="#📸-功能展示" aria-label="Permalink to &quot;📸 功能展示&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">当前资源状态</p><p>网站已内置基础 Logo、favicon 和首页主图。功能实拍截图建议后续按 <a href="./SCREENSHOTS_NEEDED.html">截图需求清单</a> 补充到 <code>docs/public/screenshots/</code>，以展示真实使用场景。</p></div><hr><h2 id="🚀-快速开始" tabindex="-1">🚀 快速开始 <a class="header-anchor" href="#🚀-快速开始" aria-label="Permalink to &quot;🚀 快速开始&quot;">​</a></h2><h3 id="_1-下载-snipx" tabindex="-1">1. 下载 SnipX <a class="header-anchor" href="#_1-下载-snipx" aria-label="Permalink to &quot;1. 下载 SnipX&quot;">​</a></h3><p>访问 <a href="/SnipX/download.html">下载页面</a> 下载最新版本。</p><h3 id="_2-运行程序" tabindex="-1">2. 运行程序 <a class="header-anchor" href="#_2-运行程序" aria-label="Permalink to &quot;2. 运行程序&quot;">​</a></h3><p>双击 <code>SnipX.exe</code> 运行程序。</p><h3 id="_3-开始截图" tabindex="-1">3. 开始截图 <a class="header-anchor" href="#_3-开始截图" aria-label="Permalink to &quot;3. 开始截图&quot;">​</a></h3><p>按 <code>Alt+X</code> 开始区域截图，或按 <code>Alt+F</code> 进行全屏截图。</p><h3 id="_4-标注和保存" tabindex="-1">4. 标注和保存 <a class="header-anchor" href="#_4-标注和保存" aria-label="Permalink to &quot;4. 标注和保存&quot;">​</a></h3><p>使用工具栏的标注工具进行标注，按 <code>Ctrl+S</code> 保存或 <code>Ctrl+C</code> 复制到剪贴板。</p><hr><h2 id="📊-性能对比" tabindex="-1">📊 性能对比 <a class="header-anchor" href="#📊-性能对比" aria-label="Permalink to &quot;📊 性能对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>体积</th><th>启动时间</th><th>内存占用</th><th>CPU 占用</th></tr></thead><tbody><tr><td><strong>SnipX</strong></td><td><strong>&lt; 1MB</strong></td><td><strong>&lt; 500ms</strong></td><td><strong>&lt; 10MB</strong></td><td><strong>&lt; 1%</strong></td></tr><tr><td>其他工具 A</td><td>~50MB</td><td>~2s</td><td>~80MB</td><td>~5%</td></tr><tr><td>其他工具 B</td><td>~30MB</td><td>~1.5s</td><td>~60MB</td><td>~3%</td></tr><tr><td>其他工具 C</td><td>~100MB</td><td>~3s</td><td>~150MB</td><td>~8%</td></tr></tbody></table><hr><h2 id="🤝-参与贡献" tabindex="-1">🤝 参与贡献 <a class="header-anchor" href="#🤝-参与贡献" aria-label="Permalink to &quot;🤝 参与贡献&quot;">​</a></h2><p>SnipX 是一个开源项目，欢迎大家参与贡献！</p><ul><li>🐛 <a href="https://github.com/vogadero/SnipX/issues" target="_blank" rel="noreferrer">报告问题</a></li><li>💡 <a href="https://github.com/vogadero/SnipX/discussions" target="_blank" rel="noreferrer">提出建议</a></li><li>🔧 <a href="https://github.com/vogadero/SnipX/pulls" target="_blank" rel="noreferrer">贡献代码</a></li><li>📖 <a href="https://github.com/vogadero/SnipX" target="_blank" rel="noreferrer">改进文档</a></li></ul><hr><h2 id="📞-联系我们" tabindex="-1">📞 联系我们 <a class="header-anchor" href="#📞-联系我们" aria-label="Permalink to &quot;📞 联系我们&quot;">​</a></h2><ul><li><strong>GitHub</strong>: <a href="https://github.com/vogadero/SnipX" target="_blank" rel="noreferrer">https://github.com/vogadero/SnipX</a></li><li><strong>Issues</strong>: <a href="https://github.com/vogadero/SnipX/issues" target="_blank" rel="noreferrer">https://github.com/vogadero/SnipX/issues</a></li><li><strong>Discussions</strong>: <a href="https://github.com/vogadero/SnipX/discussions" target="_blank" rel="noreferrer">https://github.com/vogadero/SnipX/discussions</a></li></ul><hr><div style="text-align:center;margin-top:40px;"><h2>立即开始使用 SnipX</h2><p style="font-size:18px;color:#666;">让截图回归简单与轻量</p><a href="/SnipX/download" style="display:inline-block;padding:12px 32px;background:#3eaf7c;color:white;border-radius:4px;text-decoration:none;font-weight:600;margin-top:20px;">立即下载</a></div>',34)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
